st", "Description": "Consumed energy cost"}], "DefaultPowerCost": 0.104228, "DefaultEnergyCost": 0.135343}], "Concepts": [{"Type": "INFO", "Variable": "Contracted", "Description": "Contracted power (kW)"}, {"Type": "COST_POWER", "Variable": "TotalCost", "Description": "Contracted power cost"}], "Currency": "€", "PowerUnits": "kW", "Description": "Spanish 2.0A tariff. Constant price. Without seasons.", "EnergyUnits": "kWh"}') ON CONFLICT (name) DO UPDATE SET username = EXCLUDED.username, template = EXCLUDED.template;
