,\n  ContractedPower_P3*PowerCost_P3\n)/96,\nQuarters=Quarters+1,\nMaximeterP1=max(MaximeterP1,(Period==1)?ActivePower/1000.0:0.0),\nMaximeterP2=max(MaximeterP2,(Period==2)?ActivePower/1000.0:0.0),\nMaximeterP3=max(MaximeterP3,(Period==3)?ActivePower/1000.0:0.0),\nCostP1=(MaximeterP1<=(ContractedPower_P1*0.85))?\n  ContractedPower_P1*0.85:\n  (MaximeterP1>(ContractedPower_P1*1.05))?\n    (ContractedPower_P1+2*(MaximeterP1-(ContractedPower_P1*1.05))):\n    ContractedPower_P1,\n\nCostP2=(MaximeterP2<=(ContractedPower_P2*0.85))?\n  ContractedPower_P2*0.85:\n  (MaximeterP2>(ContractedPower_P2*1.05))?\n    (ContractedPower_P2+2*(MaximeterP2-(ContractedPower_P2*1.05))):\n    ContractedPower_P2,\nCostP3=(MaximeterP3<=(ContractedPower_P3*0.85))?\n  ContractedPower_P3*0.85:\n  (MaximeterP3>(ContractedPower_P3*1.05))?\n    (ContractedPower_P3+2*(MaximeterP3-(ContractedPower_P3*1.05))):\n    ContractedPower_P3,\nTotalCost=sum(CostP1*PowerCost_P1,CostP2*PowerCost_P2,CostP3*PowerCost_P3)*Quarters/96", "Periods": [{"Name": "On-peak", "Color": "#ff7f50", "Script": "Cost=(ActiveEnergy/1000.0)*EnergyCost,\nContracted=ContractedPower,\nMaximeter=max(ActivePower/1000.0,Maximeter),\nTotalConsumed=TotalConsumed+(ActiveEnergy/1000.0),\nTotalReactive=TotalReactive+((ReactiveEnergy>0)?(ReactiveEnergy/1000.0):0.0),\nTotalCost=TotalConsumed*EnergyCost,\nPhiCos=TotalConsumed/sqrt(TotalConsumed^2+TotalReactive^2),\nReactiveCost=(PhiCos>=0.95)?\n  0.0 :\n  (PhiCos>=0.8)?\n    TotalReactive-(0.33*TotalConsumed)*0.041554:\n    TotalReactive-(0.33*TotalConsumed)*0.062332", "Concepts": [{"Type": "INFO", "Variable": "Contracted", "Description": "Contracted power (kW)"}, {"Type": "INFO", "Variable": "Maximeter", "Description": "Maximeter reading (kW)"}, {"Type": "INFO", "Variable": "TotalConsumed", "Description": "Consumed energy (kWh)"}, {"Type": "COST_ENERGY", "Variable": "TotalCost", "Description": "Consumed energy cost"}, {"Type": "INFO", "Variable": "TotalReactive", "Description": "Total reactive power (inductive - kvarh)"}, {"Type": "INFO", "Variable": "PhiCos", "Description": "Average cos(φ)"}, {"Type": "COST_ENERGY", "Variable": "ReactiveCost", "Description": "Reactive power penalty"}], "DefaultPowerCost": 0.11562465753424658, "DefaultEnergyCost": 0.1278}, {"Name": "Off-peak", "Color": "#d4f2f1", "Script": "Cost=(ActiveEnergy/1000.0)*EnergyCost,\nContracted=ContractedPower,\nMaximeter=max(ActivePower/1000.0,Maximeter),\nTotalConsumed=TotalConsumed+(ActiveEnergy/1000.0),\nTotalReactive=TotalReactive+((ReactiveEnergy>0)?(ReactiveEnergy/1000.0):0.0),\nTotalCost=TotalConsumed*EnergyCost,\nPhiCos=TotalConsumed/sqrt(TotalConsumed^2+TotalReactive^2),\nReactiveCost=(PhiCos>=0.95)?\n  0.0 :\n  (PhiCos>=0.8)?\n    TotalReactive-(0.33*TotalConsumed)*0.041554:\n    TotalReactive-(0.33*TotalConsumed)*0.062332", "Concepts": [{"Type": "INFO", "Variable": "Contracted", "Description": "Contracted power (kW)"}, {"Type": "INFO", "Variable": "Maximeter", "Description": "Maximeter reading (kW)"}, {"Type": "INFO", "Variable": "TotalConsumed", "Description": "Consumed energy (kWh)"}, {"Type": "COST_ENERGY", "Variable": "TotalCost", "Description": "Consumed energy cost"}, {"Type": "INFO", "Variable": "TotalReactive", "Description": "Total reactive power (inductive - kvarh)"}, {"Type": "INFO", "Variable": "PhiCos", "Description": "Average cos(φ)"}, {"Type": "COST_ENERGY", "Variable": "ReactiveCost", "Description": "Reactive power penalty"}], "DefaultPowerCost": 0.07014054794520548, "DefaultEnergyCost": 0.1101}, {"Name": "Super off-peak", "Color": "#20b2aa", "Script": "Cost=(ActiveEnergy/1000.0)*EnergyCost,\nContracted=ContractedPower,\nMaximeter=max(ActivePower/1000.0,Maximeter),\nTotalConsumed=TotalConsumed+(ActiveEnergy/1000.0),\nTotalCost=TotalConsumed*EnergyCost", "Concepts": [{"Type": "INFO", "Variable": "Contracted", "Description": "Contracted power (kW)"}, {"Type": "INFO", "Variable": "Maximeter", "Description": "Maximeter reading (kW)"}, {"Type": "INFO", "Variable": "TotalConsumed", "Description": "Consumed energy (kWh)"}, {"Type": "COST_ENERGY", "Variable": "TotalCost", "Description": "Consumed energy cost"}], "DefaultPowerCost": 0.04989424657534247, "DefaultEnergyCost": 0.0831}], "Concepts": [{"Type": "COST_POWER", "Variable": "TotalCost", "Description": "Contracted power cost"}], "Currency": "€", "PowerUnits": "kW", "Description": "Spanish 3.0A. With 3 diferent periods and two seasons. Maximeter is requiered and power excess are penalized.", "EnergyUnits": "kWh"}') ON CONFLICT (name) DO UPDATE SET username = EXCLUDED.username, template = EXCLUDED.template;
